-- WAKILISHA Charts 2.0 official YouTube Charts CSV export.
-- Filename generated by repository-pinned Supabase CLI 2.107.0,
-- unlinked GitHub Actions run 45429624915. No Production access.
-- A signed-in operator attests the market/week; the CSV does not embed it.
-- Preserve existing native POST, research-upload and source-method gates.
begin;
set local lock_timeout='5s';
set local statement_timeout='180s';
select pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('charts2-youtube-official-export-v1',0));

do $preimage$
begin
  if md5(pg_get_functiondef('public.charts2_commit_verified_original_v1(jsonb)'::regprocedure))
      is distinct from '0e9b13576f73fc8c92920f0ffd20b481'
    or md5(pg_get_functiondef('platform_private.charts2_compute_private_freeze_v1()'::regprocedure))
      is distinct from 'fb102f9a9007c110443165748f526d3c'
  then raise exception 'STOP: Charts2 receipt or freeze preimage drift'; end if;
  if not exists (select 1 from pg_constraint
    where conrelid='platform_private.charts2_capture_receipts_v1'::regclass
      and conname='charts2_capture_receipts_v1_capture_mode_check'
      and pg_get_constraintdef(oid) like '%research_original_upload%'
      and pg_get_constraintdef(oid) like '%service_original%'
      and pg_get_constraintdef(oid) not like '%official_export_upload%')
    or not exists (select 1 from pg_constraint
    where conrelid='platform_private.charts2_capture_receipts_v1'::regclass
      and conname='charts2_capture_receipts_v1_native_period_authority_check'
      and pg_get_constraintdef(oid) like '%provider_declared_end_date%'
      and pg_get_constraintdef(oid) not like '%operator_confirmed_official_export%')
  then raise exception 'STOP: Charts2 receipt constraint preimage drift'; end if;
end
$preimage$;

alter table platform_private.charts2_capture_receipts_v1
  drop constraint charts2_capture_receipts_v1_capture_mode_check,
  drop constraint charts2_capture_receipts_v1_native_period_authority_check,
  add constraint charts2_capture_receipts_v1_capture_mode_check
    check (capture_mode in ('research_original_upload','service_original','official_export_upload')),
  add constraint charts2_capture_receipts_v1_native_period_authority_check
    check (native_period_authority in ('unknown','observed_as_of','provider_declared_end_date','native_complete_interval','operator_confirmed_official_export')),
  add constraint charts2_receipt_official_youtube_export_v1
    check (
      (capture_mode='official_export_upload')=(native_period_authority='operator_confirmed_official_export')
      and (capture_mode<>'official_export_upload' or (
        source_key='youtube_ke' and market='KE'
        and source_endpoint='https://charts.youtube.com/charts/TopSongs/ke'
        and method_revision is null and captured_by is not null
        and original_content_type='text/csv'
        and parser_version='charts2-youtube-official-export-v1'
        and original_object_key='youtube_ke/'||left(original_sha256,2)||'/'||original_sha256||'.csv'
        and expected_depth=100 and observed_depth=100
        and provider_updated_at is null
        and provider_week_ending_date is not null
        and extract(isodow from provider_week_ending_date)=4
        and provider_week_ending_date<(observed_at at time zone 'UTC')::date
        and original_verified_at>=observed_at
      ))
    );
-- The immutable capture mode, selected end date, actor, original SHA and
-- fixed parser contract together record the explicit operator attestation.
-- No new column or change to existing receipt bytes/digests is necessary.
CREATE OR REPLACE FUNCTION public.charts2_commit_verified_original_v1(p_capture jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  src text;
  ep text;
  capture_mode text;
  sha text;
  storage_key text;
  row_data jsonb;
  row_depth integer;
  expected integer;
  receipt_id uuid;
  method_rev integer;
begin
  if p_capture is null or jsonb_typeof(p_capture) <> 'object' then
    raise exception 'charts2_receipt_payload_invalid';
  end if;
  if exists (
    select 1 from jsonb_object_keys(p_capture) as k(key)
    where k.key <> all(array[
      'source_key','source_endpoint','capture_mode','observed_at',
      'original_object_key','original_sha256','original_byte_length',
      'original_verified_at','original_content_type','expected_depth',
      'observations','parser_version','provider_updated_at',
      'provider_week_ending_date','native_period_authority',
      'method_revision','captured_by','verification_state','operator_export_acknowledgement'
    ])
  ) then
    raise exception 'charts2_receipt_extra_fields';
  end if;

  src := p_capture->>'source_key';
  ep := p_capture->>'source_endpoint';
  sha := p_capture->>'original_sha256';
  storage_key := p_capture->>'original_object_key';
  capture_mode := p_capture->>'capture_mode';
  row_data := p_capture->'observations';
  method_rev := nullif(p_capture->>'method_revision','')::integer;

  if (p_capture->>'verification_state') is distinct from 'server_sha256_storage_readback'
    or sha is null or sha !~ '^[a-f0-9]{64}$'
    or row_data is null or jsonb_typeof(row_data) <> 'array'
    or jsonb_array_length(row_data) not between 1 and 200
    or p_capture->>'captured_by' is null then
    raise exception 'charts2_receipt_unverified';
  end if;

  row_depth := jsonb_array_length(row_data);
  expected := case when src = 'shazam_ke' then 200
             when src in ('apple_ke','mdundo_ke','youtube_ke','audiomack_ke')
             then 100 else null end;
  if expected is null or p_capture->>'expected_depth' <> expected::text then
    raise exception 'charts2_receipt_source_depth_invalid';
  end if;

  if not exists (
    select 1 from storage.objects o
    where o.bucket_id = 'charts2-evidence-private-v1'
      and o.name = storage_key
  ) then
    raise exception 'charts2_private_original_missing';
  end if;

  if capture_mode is distinct from 'official_export_upload'
     and p_capture ? 'operator_export_acknowledgement' then
    raise exception using errcode='23514',message='charts2_export_acknowledgement_wrong_mode';
  end if;

  if capture_mode = 'service_original' then
    if method_rev is null or not exists (
      select 1 from platform_private.charts2_source_methods_v1 m
      where m.source_key = src
        and m.exact_endpoint = ep
        and m.method_revision = method_rev
        and (
          (m.source_key <> 'youtube_ke' and m.reviewed_method = 'GET')
          or (m.source_key = 'youtube_ke'
              and m.reviewed_method = 'POST'
              and m.exact_endpoint = 'https://charts.youtube.com/youtubei/v1/browse?alt=json')
        )
        and m.review_state = 'collector_admitted'
        and m.authorization_expires_at > now()
        and m.access_evidence_sha256 is not null
    ) then
      raise exception 'charts2_source_method_not_admitted';
    end if;
  elsif capture_mode = 'official_export_upload' then
    -- Only the signed-in, explicitly attested first-party YouTube CSV path.
    -- The selected period is operator-confirmed, NOT embedded in CSV bytes.
    if src is distinct from 'youtube_ke'
       or ep is distinct from 'https://charts.youtube.com/charts/TopSongs/ke'
       or method_rev is not null
       or p_capture->>'operator_export_acknowledgement' is distinct from
          'I confirm this unmodified YouTube Charts CSV is Kenya Weekly Top Songs for the selected week.'
       or p_capture->>'native_period_authority' is distinct from 'operator_confirmed_official_export'
       or p_capture->>'parser_version' is distinct from 'charts2-youtube-official-export-v1'
       or p_capture->>'original_content_type' is distinct from 'text/csv'
       or storage_key is distinct from 'youtube_ke/'||left(sha,2)||'/'||sha||'.csv'
       or row_depth<>100
       or p_capture->>'provider_updated_at' is not null
       or p_capture->>'provider_week_ending_date' is null
       or p_capture->>'observed_at' is null
       or p_capture->>'original_verified_at' is null
       or (p_capture->>'original_verified_at')::timestamptz < (p_capture->>'observed_at')::timestamptz
       or extract(isodow from (p_capture->>'provider_week_ending_date')::date)<>4
       or (p_capture->>'provider_week_ending_date')::date >=
          ((p_capture->>'observed_at')::timestamptz at time zone 'UTC')::date
    then
      raise exception using errcode='23514',message='charts2_youtube_export_receipt_unqualified';
    end if;
    -- Recheck the same active, unexpired capability used by the Edge session.
    if not exists (
      select 1 from public.user_role_assignments ura
      join public.role_capabilities rc on rc.role_key=ura.role_key
      where ura.user_id=(p_capture->>'captured_by')::uuid
        and ura.status='active'
        and (ura.expires_at is null or ura.expires_at>now())
        and rc.capability_key='manage_charts'
    ) then
      raise exception using errcode='42501',message='charts2_youtube_export_actor_not_authorized';
    end if;
    if not exists (
      select 1 from storage.objects o
      where o.bucket_id='charts2-evidence-private-v1' and o.name=storage_key
        and o.metadata->>'size'=p_capture->>'original_byte_length'
        and o.metadata->>'mimetype'='text/csv'
    ) then
      raise exception using errcode='23514',message='charts2_youtube_export_storage_metadata_mismatch';
    end if;
    if exists (
      select 1 from jsonb_array_elements(row_data) with ordinality as x(o,n)
      where jsonb_typeof(o) is distinct from 'object'
        or jsonb_typeof(o->'rank') is distinct from 'number'
        or o->>'rank' is distinct from n::text
        or coalesce(o->>'provider_track_id','') !~ '^[A-Za-z0-9_-]{11}$'
        or o->>'provider_url' is distinct from 'https://www.youtube.com/watch?v='||(o->>'provider_track_id')
        or jsonb_typeof(o->'title') is distinct from 'string'
        or length(btrim(coalesce(o->>'title',''))) not between 1 and 500
        or coalesce(o->>'title','') ~ '[[:cntrl:]]'
        or jsonb_typeof(o->'artist') is distinct from 'string'
        or length(btrim(coalesce(o->>'artist',''))) not between 1 and 500
        or coalesce(o->>'artist','') ~ '[[:cntrl:]]'
        or jsonb_typeof(o->'view_count') is distinct from 'number'
        or coalesce(o->>'view_count','') !~ '^(0|[1-9][0-9]{0,14})$'
    ) or (select count(distinct o->>'provider_track_id') from jsonb_array_elements(row_data) x(o))<>100 then
      raise exception using errcode='23514',message='charts2_youtube_export_rows_unqualified';
    end if;
    if exists (
      select 1 from (
        select (o->>'view_count')::bigint as views,
          lag((o->>'view_count')::bigint) over(order by n) as previous_views
        from jsonb_array_elements(row_data) with ordinality x(o,n)
      ) v where views>previous_views
    ) then
      raise exception using errcode='23514',message='charts2_youtube_export_view_order_invalid';
    end if;
  elsif capture_mode = 'research_original_upload' then
    if method_rev is not null then
      raise exception 'charts2_unadmitted_original_must_have_null_method_revision';
    end if;
  else
    raise exception 'charts2_capture_mode_invalid';
  end if;

  insert into platform_private.charts2_capture_receipts_v1
    (source_key,source_endpoint,capture_mode,observed_at,
     original_object_key,original_byte_length,original_sha256,
     original_verified_at,original_content_type,
     expected_depth,observed_depth,observations,parser_version,
     provider_updated_at,provider_week_ending_date,
     native_period_authority,method_revision,captured_by)
  values
    (src,ep,capture_mode,(p_capture->>'observed_at')::timestamptz,
     storage_key,(p_capture->>'original_byte_length')::integer,sha,
     (p_capture->>'original_verified_at')::timestamptz,
     p_capture->>'original_content_type',
     expected,row_depth,row_data,p_capture->>'parser_version',
     (p_capture->>'provider_updated_at')::timestamptz,
     (p_capture->>'provider_week_ending_date')::date,
     coalesce(p_capture->>'native_period_authority','unknown'),
     method_rev,(p_capture->>'captured_by')::uuid)
  on conflict (source_key,original_sha256) do nothing
  returning id into receipt_id;

  if receipt_id is null then
    select id into receipt_id
    from platform_private.charts2_capture_receipts_v1 r
    where r.source_key = src and r.original_sha256 = sha
      and r.original_object_key = storage_key
      and r.original_byte_length = (p_capture->>'original_byte_length')::integer
      and (
        (r.capture_mode<>'official_export_upload'
         and p_capture->>'capture_mode'<>'official_export_upload')
        or
        (r.capture_mode='official_export_upload'
         and p_capture->>'capture_mode'='official_export_upload'
         and r.source_endpoint=ep
         and r.original_content_type=p_capture->>'original_content_type'
         and r.parser_version=p_capture->>'parser_version'
         and r.native_period_authority=p_capture->>'native_period_authority'
         and r.provider_week_ending_date=(p_capture->>'provider_week_ending_date')::date
         and r.observations=row_data)
      );
    if receipt_id is null then
      if p_capture->>'capture_mode'='official_export_upload' then
        raise exception using errcode='PT409',message='charts2_duplicate_original_provenance_conflict';
      end if;
      raise exception 'charts2_duplicate_original_provenance_conflict';
    end if;
  end if;
  return receipt_id;
end;
$function$;

CREATE OR REPLACE FUNCTION platform_private.charts2_compute_private_freeze_v1()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog,public,platform_private,extensions'
AS $function$
declare
  s jsonb;
  r jsonb;
  o jsonb;
  l jsonb;
  p jsonb;
  links jsonb;
  observation_reviews jsonb;
  scores jsonb:='{}'::jsonb;
  seen_tracks jsonb:='{}'::jsonb;
  seen_ranks jsonb;
  source_receipts jsonb:='[]'::jsonb;
  input jsonb;
  ranking jsonb;
  input_sha text;
  rank_sha text;
  source_key text;
  provider_key text;
  expected_endpoint text;
  official_export boolean;
  original_sha text;
  expected_depth integer;
  source_weight integer;
  observed_rank integer;
  rank_count integer;
  credit_units integer;
  receipt_id text;
  provider_id text;
  track_uuid text;
  eligible integer;
  source_count integer:=0;
  unresolved integer:=0;
  conflicts integer:=0;
  matches integer;
  existing jsonb;
  max_sources integer;
  required_weights constant jsonb :=
    '{"youtube_ke":30,"mdundo_ke":25,"apple_ke":20,"audiomack_ke":15,"shazam_ke":10}'::jsonb;
begin
  s:=public.charts2_studio_private_snapshot_v1();
  if s->>'contract' is distinct from 'charts2-private-studio/v1'
     or s->'methodology'->>'version' is distinct from
        'consumption_led_cultural_presence_v1'
     or s->'methodology'->>'scoring_policy_version' is distinct from
        'charts2-private-ordinal-v1'
     or s->'methodology'->'rule_set'->'weights' is distinct from required_weights
     or (s->'methodology'->'rule_set'->>'unit_denominator')::integer
          is distinct from 200
  then raise exception 'charts2_freeze_methodology_drift'; end if;
  if jsonb_typeof(s->'receipts') is distinct from 'array'
     or jsonb_array_length(s->'receipts')<>5
  then raise exception 'charts2_freeze_requires_five_receipts'; end if;
  links:=coalesce(s->'registry_links','[]'::jsonb);
  if jsonb_typeof(links)<>'array'
  then raise exception 'charts2_freeze_registry_snapshot_invalid'; end if;
  observation_reviews:=coalesce(s->'observation_reviews','[]'::jsonb);
  if jsonb_typeof(observation_reviews)<>'array'
  then raise exception 'charts2_freeze_observation_reviews_invalid'; end if;
  for r in select value from jsonb_array_elements(s->'receipts')
             order by value->>'source_key' loop
    source_count:=source_count+1;
    source_key:=r->>'source_key';
    case source_key
      when 'youtube_ke' then
        provider_key:='youtube';expected_depth:=100;source_weight:=30;
        expected_endpoint:='https://charts.youtube.com/youtubei/v1/browse?alt=json';
      when 'mdundo_ke' then
        provider_key:='mdundo';expected_depth:=100;source_weight:=25;
        expected_endpoint:='https://play.mdundo.com/top-charts/ke';
      when 'apple_ke' then
        provider_key:='apple_music';expected_depth:=100;source_weight:=20;
        expected_endpoint:='https://music.apple.com/ke/playlist/top-100-kenya/pl.0b36ea82865d4adeb9d1d62207aab172';
      when 'audiomack_ke' then
        provider_key:='audiomack';expected_depth:=100;source_weight:=15;
        expected_endpoint:='https://audiomack.com/geo-charts/playlist/kenya';
      when 'shazam_ke' then
        provider_key:='shazam';expected_depth:=200;source_weight:=10;
        expected_endpoint:='https://www.shazam.com/services/charts/csv/top-200/kenya';
      else raise exception 'charts2_freeze_source_invalid';
    end case;
    official_export:=(r->>'capture_mode') is not distinct from 'official_export_upload';
    if official_export then
      if source_key<>'youtube_ke'
         or r->>'native_period_authority' is distinct from 'operator_confirmed_official_export'
         or r->>'original_content_type' is distinct from 'text/csv'
         or r->>'parser_version' is distinct from 'charts2-youtube-official-export-v1'
         or r->>'method_revision' is not null
         or r->>'provider_updated_at' is not null
         or nullif(r->>'provider_week_ending_date','') is null
         or extract(isodow from (r->>'provider_week_ending_date')::date)<>4
         or (r->>'provider_week_ending_date')::date >=
            ((r->>'observed_at')::timestamptz at time zone 'UTC')::date
      then raise exception 'charts2_freeze_youtube_export_unqualified'; end if;
      expected_endpoint:='https://charts.youtube.com/charts/TopSongs/ke';
    elsif r->>'native_period_authority'='operator_confirmed_official_export' then
      raise exception 'charts2_freeze_youtube_export_unqualified';
    end if;
    if (source_receipts @> jsonb_build_array(jsonb_build_object('source_key',source_key)))
    then raise exception 'charts2_freeze_duplicate_source'; end if;
    receipt_id:=r->>'id';
    original_sha:=r->>'original_sha256';
    if r->>'receipt_schema' is distinct from 'charts2-original-receipt/v1'
       or r->>'source_endpoint' is distinct from expected_endpoint
       or r->>'market' is distinct from 'KE'
       or (not official_export and r->>'capture_mode' is distinct from 'service_original')
       or r->>'original_bucket' is distinct from 'charts2-evidence-private-v1'
       or original_sha !~ '^[a-f0-9]{64}$'
       or r->>'original_object_key' is distinct from
         source_key||'/'||left(original_sha,2)||'/'||original_sha||
         (case when official_export then '.csv' when source_key='youtube_ke' then '.json'
               when source_key='shazam_ke' then '.csv' else '.html' end)
       or coalesce((r->>'original_byte_length')::integer,0) not between 1 and 4000000
       or (not official_export and coalesce((r->>'method_revision')::integer,0)<1)
       or coalesce((r->>'expected_depth')::integer,0)<>expected_depth
       or coalesce((r->>'observed_depth')::integer,0)<>expected_depth
       or r->>'observed_status' is distinct from 'succeeded'
       or (r->>'candidate_only')::boolean is distinct from true
       or (r->>'can_score')::boolean is distinct from false
       or (r->>'can_publish')::boolean is distinct from false
       or nullif(r->>'observed_at','') is null
       or nullif(r->>'original_verified_at','') is null
       or (r->>'observed_at')::timestamptz >
           (r->>'original_verified_at')::timestamptz
       or jsonb_typeof(r->'observations') is distinct from 'array'
       or jsonb_array_length(r->'observations')<>expected_depth
    then raise exception 'charts2_freeze_receipt_unqualified_%',source_key; end if;
    if source_key='youtube_ke' and not official_export and (
       r->>'native_period_authority' is distinct from 'provider_declared_end_date'
       or nullif(r->>'provider_week_ending_date','') is null
    ) then raise exception 'charts2_freeze_youtube_week_unqualified'; end if;
    source_receipts:=source_receipts||jsonb_build_array(jsonb_build_object(
      'source_key',source_key,'receipt_id',receipt_id,'original_sha256',original_sha,
      'native_period_authority',r->>'native_period_authority',
      'observed_at',r->>'observed_at',
      'provider_updated_at',r->>'provider_updated_at',
      'provider_week_ending_date',r->>'provider_week_ending_date'));
    seen_ranks:='{}'::jsonb;
    for o in select value from jsonb_array_elements(r->'observations') loop
      if coalesce((o->>'rank') ~ '^[0-9]+$',false) is false
      then raise exception 'charts2_freeze_rank_invalid'; end if;
      observed_rank:=(o->>'rank')::integer;
      if observed_rank<1 or observed_rank>expected_depth or
         seen_ranks ? observed_rank::text or nullif(o->>'title','') is null
      then raise exception 'charts2_freeze_rank_or_title_invalid'; end if;
      seen_ranks:=seen_ranks||jsonb_build_object(observed_rank::text,true);
      if official_export and (
        coalesce(o->>'provider_track_id','') !~ '^[A-Za-z0-9_-]{11}$'
        or o->>'provider_url' is distinct from 'https://www.youtube.com/watch?v='||(o->>'provider_track_id')
        or nullif(btrim(coalesce(o->>'artist','')),'') is null
        or jsonb_typeof(o->'view_count') is distinct from 'number'
        or coalesce(o->>'view_count','') !~ '^(0|[1-9][0-9]{0,14})$'
      ) then raise exception 'charts2_freeze_youtube_export_rows_unqualified';end if;
      provider_id:=nullif(o->>'provider_track_id','');
      matches:=0;l:=null;
      if provider_id is null then
        if source_key<>'shazam_ke'
        then unresolved:=unresolved+1;continue;end if;
        for p in select value from jsonb_array_elements(observation_reviews) loop
          if p->>'source_key' is distinct from source_key
            or p->>'receipt_id' is distinct from receipt_id
            or p->>'original_sha256' is distinct from original_sha
            or p->>'rank' is distinct from observed_rank::text
            or p->>'title' is distinct from o->>'title'
            or nullif(p->>'artist','') is distinct from nullif(o->>'artist','')
            or p->>'provider_track_id' is not null
            or p->>'action' is distinct from 'approve'
            or p->>'track_status' is distinct from 'active'
            or coalesce(p->>'event_fingerprint','') !~ '^[a-f0-9]{64}$'
            or length(btrim(coalesce(p->>'review_note','')))<40
            or coalesce(p->>'evidence_url','') not like 'https://%'
          then continue;end if;
          matches:=matches+1;l:=p;
        end loop;
      else
      for p in select value from jsonb_array_elements(links) loop
        if p->>'provider_key' is distinct from provider_key or
           p->>'provider_track_id' is distinct from provider_id
        then continue; end if;
        -- The actual Registry admits only manual, isrc and title/artist
        -- methods. A mere label claiming exact ID is NOT accepted authority.
        if p->>'track_status' is distinct from 'active'
           or p->>'match_status' is distinct from 'matched'
           or p->>'match_method' is distinct from 'manual'
           or (p->>'match_confidence')::numeric is distinct from 1
        then continue; end if;
        -- Exact provenance, reviewed by the existing Registry broker.
        if p->'review_evidence'->>'charts2_studio_review_v1' is distinct from 'true'
           or p->'review_evidence'->>'source_key' is distinct from source_key
           or p->'review_evidence'->>'receipt_id' is distinct from receipt_id
           or p->'review_evidence'->>'original_sha256' is distinct from original_sha
           or p->'review_evidence'->>'provider_track_id' is distinct from provider_id
           or length(btrim(coalesce(p->'review_evidence'->>'review_note','')))<40
           or coalesce(p->'review_evidence'->>'evidence_url','') not like 'https://%'
        then continue; end if;
        matches:=matches+1;l:=p;
      end loop;
      end if;
      if matches=0 then unresolved:=unresolved+1;continue; end if;
      if matches<>1 then conflicts:=conflicts+1;continue; end if;
      track_uuid:=l->>'track_id';
      if track_uuid is null then conflicts:=conflicts+1;continue; end if;
      if seen_tracks ? (source_key||'/'||track_uuid) then
        conflicts:=conflicts+1;continue;
      end if;
      seen_tracks:=seen_tracks||jsonb_build_object(source_key||'/'||track_uuid,true);
      credit_units:=source_weight*(200/expected_depth)*
        (expected_depth-observed_rank+1);
      existing:=coalesce(scores->track_uuid,
        jsonb_build_object('track_id',track_uuid,'score_units',0,
          'source_contributions','[]'::jsonb));
      scores:=jsonb_set(scores,array[track_uuid],
        jsonb_build_object('track_id',track_uuid,
          'score_units',(existing->>'score_units')::integer+credit_units,
          'source_contributions',existing->'source_contributions'||
            jsonb_build_array(jsonb_build_object(
              'source_key',source_key,'receipt_id',receipt_id,
              'original_sha256',original_sha,'rank',observed_rank,
              'source_weight_points',source_weight,
              'credit_units',credit_units) ||
              case when provider_id is null
                then jsonb_build_object('registry_observation_resolution_id',l->>'id')
                else jsonb_build_object('registry_provider_link_id',l->>'id')
              end)),
        true);
    end loop;
    select count(*) into rank_count from jsonb_object_keys(seen_ranks);
    if rank_count<>expected_depth
    then raise exception 'charts2_freeze_rank_depth_gap'; end if;
  end loop;
  if source_count<>5 then raise exception 'charts2_freeze_source_count_invalid';end if;
  select count(*) into eligible from jsonb_each(scores);
  select coalesce(jsonb_agg(jsonb_build_object(
        'position',pos,'track_id',track_id,'score_units',units,
        'score_points',to_char(units::numeric/200,'FM999990.00'),
        'source_contributions',contributions) order by pos),'[]'::jsonb)
  into ranking
  from (
    select row_number() over (order by units desc,track_id asc)::integer as pos,
      track_id,units,contributions
    from (
      select key as track_id,(value->>'score_units')::integer as units,
        value->'source_contributions' as contributions
      from jsonb_each(scores)
    ) ordered_scores
  ) numbered
  where pos<=100;
  input:=jsonb_build_object(
    'methodology',s->'methodology','receipts',s->'receipts',
    'registry_links',s->'registry_links','observation_reviews',s->'observation_reviews',
    'review_policy','exact_manual_receipt_plus_shazam_v1');
  input_sha:=encode(extensions.digest(input::text,'sha256'),'hex');
  rank_sha:=encode(extensions.digest(ranking::text,'sha256'),'hex');
  return jsonb_build_object('contract','charts2-private-freeze-preflight/v1',
    'methodology_version','consumption_led_cultural_presence_v1',
    'scoring_policy_version','charts2-private-ordinal-v1',
    'input_sha256',input_sha,'ranking_sha256',rank_sha,
    'eligible_count',eligible,'unresolved_count',unresolved,'conflict_count',conflicts,
    'source_receipts',source_receipts,'ranking',ranking,
    'freeze_ready',eligible>=100 and conflicts=0,
    'can_publish',false);
end
$function$;

-- CREATE OR REPLACE retains existing ACLs; assert the unchanged fences.
do $acl$
begin
  if not has_function_privilege('service_role','public.charts2_commit_verified_original_v1(jsonb)','EXECUTE')
    or has_function_privilege('anon','public.charts2_commit_verified_original_v1(jsonb)','EXECUTE')
    or has_function_privilege('authenticated','public.charts2_commit_verified_original_v1(jsonb)','EXECUTE')
    or has_function_privilege('anon','platform_private.charts2_compute_private_freeze_v1()','EXECUTE')
    or has_function_privilege('authenticated','platform_private.charts2_compute_private_freeze_v1()','EXECUTE')
    or has_function_privilege('service_role','platform_private.charts2_compute_private_freeze_v1()','EXECUTE')
  then raise exception 'STOP: Charts2 private RPC privileges changed';end if;
end
$acl$;
commit;
